/**
 * Dataverse option set `systemuser_invitestatuscode`.
 *
 * - `0`: InvitationNotSent
 * - `1`: Invited
 * - `2`: InvitationNearExpired
 * - `3`: InvitationExpired
 * - `4`: InvitationAccepted
 * - `5`: InvitationRejected
 * - `6`: InvitationRevoked
 */
declare type systemuser_invitestatuscode = 0 | 1 | 2 | 3 | 4 | 5 | 6;
